INSERT INTO `courses` (`id`, `teacher_id`, `title`, `slug`, `short_description`, `description`, `objectives`, `prerequisites`, `duration_hours`, `level`, `education_level`, `format`, `category`, `price`, `cover_image`, `status`, `sequential_modules`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 12, 'Formation Développement Web : Devenir Développeur Full-Stack', 'formation-developpement-web-full-stack', 'Maîtrisez les technologies clés du web (HTML, CSS, JavaScript, React et Node.js) pour concevoir et déployer des sites internet et des applications web modernes.', 'Ce cursus intensif et pratique est conçu pour vous propulser dans le monde de la programmation. Vous apprendrez à créer des interfaces utilisateur dynamiques (Front-end) et à configurer des serveurs et bases de données robustes (Back-end). À travers des projets concrets, vous adopterez les meilleures pratiques de code et les outils professionnels indispensables (Git, GitHub, VS Code).', 'Structurer et styliser des pages web modernes et responsives.Dynamiser des interfaces utilisateur et gérer l\'asynchronisme.Développer des applications complètes avec une architecture Front/Back.Créer et consommer des API REST de manière sécurisée.', 'Aisance avec l\'outil informatique. Aucune base en programmation n\'est requise.', '40.00', 'beginner', NULL, 'online', 'Informatique / Technologies du Web', '599.63', 'bd3606665455736c39919213e13e6903.png', 'published', 0, '2026-09-04 08:31:55', '2026-09-04 09:30:30', '2026-09-25 08:37:16'),
(2, NULL, 'formation comptable', 'comptable', NULL, NULL, NULL, NULL, '50.00', 'beginner', NULL, 'hybrid', 'comptable', '500.00', '1e688e9e93abc00f2423ef9d605f0668.jpg', 'published', 0, '2026-09-14 14:03:16', '2026-09-14 15:03:16', '2026-09-14 15:03:16'),
(3, NULL, 'test', 'test-test', 'test1', 'test2', 'test3', 'test4', '50.00', 'beginner', NULL, 'online', 'test_categ', '200.00', NULL, 'published', 0, '2026-09-24 09:43:17', '2026-09-24 10:41:22', '2026-09-24 10:43:17'),
(6, 12, 'info', 'testtest', 't', 't', 't', 't', '500.00', 'advanced', 'higher_education', 'hybrid', 'Informatique / Technologies du Web', '999.72', '9a562ed7379337a9fab49eee2e748e5e.jpg', 'published', 0, '2026-10-20 11:53:14', '2026-10-20 12:53:14', '2026-10-20 12:53:14');
